oxy_webhelp_navlinks = {"rcv_security-d39536e10491":{"topics":[{"title":"RCV security for data center workloads","shortdesc":"<p class=\"shortdesc\">Rubrik Cloud Vault adheres to security standards for the protection of archived         backups from data center workloads.<\/p>","href":"saas\/rcv_security_dc_workloads.html","attributes":{"data-id":"rcv_security_dc_workloads"},"menu":{"hasChildren":false},"tocID":"rcv_security_dc_workloads-d39536e10502","topics":[]},{"title":"Immutable Rubrik Cloud Vault locations","shortdesc":"<p class=\"shortdesc\">Rubrik Cloud Vault locations provide immutability for cloud-native, <span class=\"ph\">NAS CD<\/span>, and data center workloads, depending on the Rubrik CDM version and the         cloud provider. Immutability ensures retention policies are enforced and prevents alteration         or deletion of snapshots for the specified period, safeguarding data integrity.<\/p>","href":"saas\/immutable_rcv_locations.html","attributes":{"data-id":"immutable_rcv_locations"},"menu":{"hasChildren":false},"tocID":"immutable_rcv_locations-d39536e10513","next":"immutable_rcv_locations-d39536e10513"},{"title":"RCV encryption options","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports client-side encryption for data center RCV locations and         server-side encryption for cloud-native protection and NAS Cloud Direct RCV         locations.<\/p>","href":"saas\/rcv_encryption_options.html","attributes":{"data-id":"rcv_encryption_options"},"menu":{"hasChildren":false},"tocID":"rcv_encryption_options-d39536e10566","topics":[]},{"title":"Quorum authorization for Rubrik Cloud Vault management actions","shortdesc":"<p class=\"shortdesc\">You can protect the management actions on your Rubrik Cloud Vault locations using         quorum authorization. When enabled, quorum authorization requires the requesters of the         protected actions to obtain additional approvals to perform the requested         actions.<\/p>","href":"saas\/qauth_for_rcv.html","attributes":{"data-id":"qauth_for_rcv"},"menu":{"hasChildren":false},"tocID":"qauth_for_rcv-d39536e10579","next":"qauth_for_rcv-d39536e10579"}]}};